import http from 'http';
function mk(): any { return function (...a: any[]) { return a.length; }; }
function main(): void {
  const d: any = { n: 7, fn: (x: number) => x * 2, g: function (x: number) { return x + 1; } };
  const keys = Object.keys(d);
  console.log(d[keys[1]](4), d[keys[2]](4));
  const name = keys[1];
  console.log(d[name](3), typeof d.g, d.g.name);
  const run = (cb: any) => cb(10);
  console.log(run(d.g));
  const s = http.createServer(mk());
  s.listen(0, function () { console.log(typeof this.address().port); s.close(); });
}
